package irvine.math.group;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.BitSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

import irvine.math.z.Z;

/**
 * Orbits of binary matrix spaces generated by rank-one matrices.
 * @author Gregory Morse
 */
public final class RankOneMatrixSubspaces {

  private final int mN;
  private final int mWidth;
  private final int mMask;
  private final int mIdentity;
  private final Map<Integer, int[]> mPermutations = new HashMap<>();
  private final int[] mElimination = new int[8];
  private final long[] mTensorElimination = new long[64];

  private RankOneMatrixSubspaces(final int n) {
    mN = n;
    mWidth = 1 << n;
    mMask = mWidth - 1;
    int id = 0;
    for (int k = 0; k < n; ++k) {
      id |= k << (4 * k);
    }
    mIdentity = id;
  }

  private static final class LongIndex {
    private final long[] mKeys;
    private final int[] mValues;
    private final int mMask;

    private LongIndex(final long[] codes) {
      int capacity = 2;
      while (capacity < 2 * codes.length) {
        capacity *= 2;
      }
      mKeys = new long[capacity];
      mValues = new int[capacity];
      mMask = capacity - 1;
      for (int k = 0; k < codes.length; ++k) {
        final long x = codes[k];
        final int s = slot(x);
        mKeys[s] = x;
        mValues[s] = k;
      }
    }

    private int slot(long key) {
      final long x = key;
      key = (key ^ (key >>> 33)) * 0xff51afd7ed558ccdL;
      key = (key ^ (key >>> 33)) * 0xc4ceb9fe1a85ec53L;
      int s = (int) (key ^ (key >>> 33)) & mMask;
      while (mKeys[s] != 0 && mKeys[s] != x) {
        s = (s + 1) & mMask;
      }
      return s;
    }

    private int index(final long key) {
      final int s = slot(key);
      if (mKeys[s] == 0) {
        throw new IllegalStateException("Unknown full-support row space");
      }
      return mValues[s];
    }
  }

  private long rref(long rows) {
    Arrays.fill(mElimination, 0);
    while (rows != 0) {
      int r = (int) rows & mMask;
      rows >>>= mN;
      while (r != 0) {
        final int p = Integer.highestOneBit(r);
        final int k = Integer.numberOfTrailingZeros(p);
        if (mElimination[k] == 0) {
          mElimination[k] = r;
          break;
        }
        r ^= mElimination[k];
      }
    }
    for (int k = 0; k < mN; ++k) {
      if (mElimination[k] != 0) {
        for (int j = k + 1; j < mN; ++j) {
          if ((mElimination[j] & (1 << k)) != 0) {
            mElimination[j] ^= mElimination[k];
          }
        }
      }
    }
    long code = 0;
    int shift = 0;
    for (final int r : mElimination) {
      if (r != 0) {
        code |= (long) r << shift;
        shift += mN;
      }
    }
    return code;
  }

  private final class Codes {
    private final long[] mCodes;
    private final LongIndex mIndex;
    private final Map<int[], int[]> mTranspositions = new IdentityHashMap<>();

    private Codes(final long[] codes) {
      mCodes = codes;
      mIndex = new LongIndex(codes);
    }

    private int[] transposition(final int[] g) {
      int moved = 0;
      for (int k = 0; k < mN; ++k) {
        if (g[1 << k] != (1 << k)) {
          ++moved;
        }
      }
      if (moved != 2) {
        return null;
      }
      // A column swap recurs in many stabilizers. Cache only those
      // O(n^2) actions, rather than full permutation representations.
      return mTranspositions.computeIfAbsent(g, p -> {
        final int[] map = new int[mCodes.length];
        for (int k = 0; k < map.length; ++k) {
          map[k] = mIndex.index(permute(mCodes[k], p));
        }
        return map;
      });
    }
  }

  private void generate(final List<Long> result, final int pivots, final int left,
                        final int shift, final long rows, final int support) {
    if (left == 0) {
      if (support == mMask) {
        result.add(rows);
      }
      return;
    }
    final int pivot = Integer.lowestOneBit(left);
    final int allowed = (pivot - 1) & ~pivots;
    for (int tail = allowed; ; tail = (tail - 1) & allowed) {
      final int row = pivot | tail;
      generate(result, pivots, left ^ pivot, shift + mN, rows | ((long) row << shift), support | row);
      if (tail == 0) {
        break;
      }
    }
  }

  private Codes codes(final int rank) {
    final List<Long> codes = new ArrayList<>();
    for (int pivots = 1; pivots < mWidth; ++pivots) {
      if (Integer.bitCount(pivots) == rank) {
        generate(codes, pivots, pivots, 0, 0, 0);
      }
    }
    return new Codes(codes.stream().mapToLong(Long::longValue).toArray());
  }

  private static int image(final int permutation, final int k) {
    return (permutation >>> (4 * k)) & 15;
  }

  private int compose(final int a, final int b) {
    int code = 0;
    for (int k = 0; k < mN; ++k) {
      code |= image(a, image(b, k)) << (4 * k);
    }
    return code;
  }

  private int inverse(final int a) {
    int code = 0;
    for (int k = 0; k < mN; ++k) {
      code |= k << (4 * image(a, k));
    }
    return code;
  }

  private int[] permutation(final int p) {
    return mPermutations.computeIfAbsent(p, k -> {
      final int[] map = new int[mWidth];
      for (int x = 1; x < map.length; ++x) {
        map[x] = map[x & (x - 1)] | (1 << image(p, Integer.numberOfTrailingZeros(x)));
      }
      return map;
    });
  }

  private long permute(long rows, final int[] p) {
    long code = 0;
    for (int shift = 0; rows != 0; shift += mN) {
      code |= (long) p[(int) rows & mMask] << shift;
      rows >>>= mN;
    }
    return rref(code);
  }

  private final class Stabilizer {
    private final Set<Integer> mKnown = new HashSet<>();
    private final List<Integer> mElements = new ArrayList<>();
    private final List<Integer> mGenerators = new ArrayList<>();

    private Stabilizer() {
      mKnown.add(mIdentity);
      mElements.add(mIdentity);
    }

    private void add(final int p) {
      if (!mKnown.contains(p)) {
        mGenerators.add(p);
        for (int i = 0; i < mElements.size(); ++i) {
          for (final int g : mGenerators) {
            final int h = compose(mElements.get(i), g);
            if (mKnown.add(h)) {
              mElements.add(h);
            }
          }
        }
      }
    }
  }

  private final class LeftOrbits {
    private final int[] mOrbit;
    private final int[] mTransport;
    private final List<Long> mReps = new ArrayList<>();
    private final List<int[][]> mStabilizers = new ArrayList<>();

    private LeftOrbits(final Codes left) {
      mOrbit = new int[left.mCodes.length];
      mTransport = new int[mOrbit.length];
      Arrays.fill(mOrbit, -1);
      final int[] swaps = new int[mN - 1];
      final int[][] actions = new int[swaps.length][];
      for (int k = 0; k < swaps.length; ++k) {
        final int diff = k ^ (k + 1);
        swaps[k] = mIdentity ^ (diff << (4 * k)) ^ (diff << (4 * (k + 1)));
        actions[k] = left.transposition(permutation(swaps[k]));
      }
      final int[] queue = new int[mOrbit.length];
      for (int rep = 0; rep < mOrbit.length; ++rep) {
        if (mOrbit[rep] < 0) {
          final int c = mReps.size();
          mReps.add(left.mCodes[rep]);
          final Stabilizer stabilizer = new Stabilizer();
          mOrbit[rep] = c;
          mTransport[rep] = mIdentity;
          queue[0] = rep;
          int end = 1;
          for (int k = 0; k < end; ++k) {
            final int x = queue[k];
            for (int j = 0; j < swaps.length; ++j) {
              final int y = actions[j][x];
              final int route = compose(mTransport[x], swaps[j]);
              if (mOrbit[y] < 0) {
                mOrbit[y] = c;
                mTransport[y] = route;
                queue[end++] = y;
              } else if (route != mTransport[y]) {
                // Schreier generator at the representative.
                stabilizer.add(compose(mTransport[y], inverse(route)));
              }
            }
          }
          mStabilizers.add(stabilizer.mGenerators.stream().map(RankOneMatrixSubspaces.this::permutation).toArray(int[][]::new));
        }
      }
    }
  }

  private static final class Components {
    private int[] mParent = new int[1024];
    private int mSize = 0;
    private long mCount = 0;

    private int add() {
      if (mSize == mParent.length) {
        mParent = Arrays.copyOf(mParent, 2 * mSize);
      }
      mParent[mSize] = -1;
      ++mCount;
      return mSize++;
    }

    private int root(int a) {
      while (mParent[a] >= 0) {
        final int p = mParent[a];
        if (mParent[p] >= 0) {
          mParent[a] = mParent[p];
        }
        a = p;
      }
      return a;
    }

    private void join(final int a, final int b) {
      int x = root(a);
      int y = root(b);
      if (x != y) {
        if (mParent[x] > mParent[y]) {
          final int t = x;
          x = y;
          y = t;
        }
        mParent[x] += mParent[y];
        mParent[y] = x;
        --mCount;
      }
    }
  }

  private void columns(long rows, final int[] columns) {
    Arrays.fill(columns, 0);
    int bit = 1;
    while (rows != 0) {
      for (int r = (int) rows & mMask; r != 0; r &= r - 1) {
        columns[Integer.numberOfTrailingZeros(r)] |= bit;
      }
      bit <<= 1;
      rows >>>= mN;
    }
  }

  private final class Pairs {
    private final Codes mLeft;
    private final Codes mRight;
    private final LeftOrbits mOrbits;
    private final int mLeftRank;
    private final int mRightRank;
    private final int mRightMask;
    private final long mRowStarts;
    private final long[][] mOuter;
    private final long[] mColumnUpdate;
    private final int[] mU = new int[mN];
    private final int[] mV = new int[mN];
    private final Components mComponents = new Components();
    private final int[][] mNode;
    private final BitSet[] mRepresentatives;

    private Pairs(final Codes left, final Codes right, final LeftOrbits orbits, final int a, final int b) {
      mLeft = left;
      mRight = right;
      mOrbits = orbits;
      mLeftRank = a;
      mRightRank = b;
      mRightMask = (1 << b) - 1;
      long starts = 0;
      for (int j = 0; j < a; ++j) {
        starts |= 1L << (j * b);
      }
      mRowStarts = starts;
      mOuter = new long[1 << a][1 << b];
      for (int u = 1; u < mOuter.length; ++u) {
        final int row = Integer.numberOfTrailingZeros(u);
        for (int v = 1; v <= mRightMask; ++v) {
          mOuter[u][v] = mOuter[u & (u - 1)][v] | ((long) v << (row * b));
        }
      }
      mColumnUpdate = new long[1 << b];
      for (int v = 1; v < mColumnUpdate.length; ++v) {
        mColumnUpdate[v] = mColumnUpdate[v & (v - 1)] | (1L << (Integer.numberOfTrailingZeros(v) * mN));
      }
      mNode = new int[orbits.mReps.size()][];
      mRepresentatives = new BitSet[mNode.length];
    }

    private boolean independent(final long a, final long b) {
      columns(a, mU);
      columns(b, mV);
      Arrays.fill(mTensorElimination, 0);
      for (int k = 0; k < mN; ++k) {
        long v = mOuter[mU[k]][mV[k]];
        while (v != 0) {
          final int p = Long.numberOfLeadingZeros(v);
          if (mTensorElimination[p] == 0) {
            mTensorElimination[p] = v;
            break;
          }
          v ^= mTensorElimination[p];
        }
        if (v == 0) {
          return false;
        }
      }
      return true;
    }

    private void classify() {
      final int[] queue = new int[mRight.mCodes.length];
      for (int c = 0; c < mNode.length; ++c) {
        final long left = mOrbits.mReps.get(c);
        final int[][] generators = mOrbits.mStabilizers.get(c);
        final int[][] actions = new int[generators.length][];
        for (int j = 0; j < actions.length; ++j) {
          actions[j] = mRight.transposition(generators[j]);
        }
        final int[] ids = new int[mRight.mCodes.length];
        final BitSet reps = new BitSet(ids.length);
        Arrays.fill(ids, -2);
        mNode[c] = ids;
        mRepresentatives[c] = reps;
        for (int x = 0; x < ids.length; ++x) {
          if (ids[x] == -2) {
            final int id = independent(left, mRight.mCodes[x]) ? mComponents.add() : -1;
            if (id >= 0) {
              reps.set(x);
            }
            ids[x] = id;
            queue[0] = x;
            int end = 1;
            for (int k = 0; k < end; ++k) {
              final int r = queue[k];
              for (int j = 0; j < generators.length; ++j) {
                final int[] action = actions[j];
                final int y = action == null ? mRight.mIndex.index(permute(mRight.mCodes[r], generators[j])) : action[r];
                if (ids[y] == -2) {
                  ids[y] = id;
                  queue[end++] = y;
                }
              }
            }
          }
        }
      }
    }

    private void exchange(final long left, final long right, final int node, final int k, final int u, final int v) {
      final int l = mLeft.mIndex.index(rref(left ^ (mColumnUpdate[mU[k] ^ u] << k)));
      final long newRight = right ^ (mColumnUpdate[mV[k] ^ v] << k);
      final int r = mRight.mIndex.index(permute(newRight, permutation(mOrbits.mTransport[l])));
      final int neighbor = mNode[mOrbits.mOrbit[l]][r];
      if (neighbor < 0) {
        throw new IllegalStateException("Basis exchange lost independence");
      }
      mComponents.join(node, neighbor);
    }

    private void merge() {
      final long[] sums = new long[mWidth];
      for (int c = 0; c < mNode.length; ++c) {
        final long left = mOrbits.mReps.get(c);
        for (int r = mRepresentatives[c].nextSetBit(0); r >= 0; r = mRepresentatives[c].nextSetBit(r + 1)) {
          final long right = mRight.mCodes[r];
          final int node = mNode[c][r];
          columns(left, mU);
          columns(right, mV);
          for (int x = 1; x < mWidth; ++x) {
            final int k = Integer.numberOfTrailingZeros(x);
            final int rest = x & (x - 1);
            final long sum = sums[rest] ^ mOuter[mU[k]][mV[k]];
            sums[x] = sum;
            if (rest != 0) {
              final int pivot = Long.numberOfTrailingZeros(sum);
              final int column = pivot % mRightRank;
              final int v = (int) (sum >>> (pivot - column)) & mRightMask;
              final long rows = (sum >>> column) & mRowStarts;
              // Row slots are disjoint, so multiplication reconstructs
              // the matrix exactly when every nonzero row equals v.
              if (rows * v == sum) {
                int u = 0;
                for (long j = rows; j != 0; j &= j - 1) {
                  u |= 1 << (Long.numberOfTrailingZeros(j) / mRightRank);
                }
                for (int y = x; y != 0; y &= y - 1) {
                  exchange(left, right, node, Integer.numberOfTrailingZeros(y), u, v);
                }
              }
            }
          }
        }
      }
    }
  }

  private long count() {
    final Codes[] codes = new Codes[mN + 1];
    for (int r = 1; r <= mN; ++r) {
      codes[r] = codes(r);
    }
    long total = 0;
    for (int a = 1; a <= mN; ++a) {
      final LeftOrbits orbits = new LeftOrbits(codes[a]);
      // If the right columns form a basis, rank-one exchanges take place
      // within groups of equal left columns and do not change the left code.
      total += (a == mN ? 1 : 2) * (long) orbits.mReps.size();
      for (int b = a; b < mN; ++b) {
        final int codimension = a * b - mN;
        final int multiplicity = a == b ? 1 : 2;
        if (codimension == 0) {
          total += multiplicity;
        } else if (codimension == 1) {
          // A hyperplane is classified by the rank of its defining
          // bilinear form. In diagonal coordinates the off-diagonal
          // tensors and (e_i+e_j)(f_i+f_j)^t span the kernel, together
          // with any diagonal tensors on which the form vanishes.
          total += (long) multiplicity * a;
        } else if (codimension > 1) {
          final Pairs pairs = new Pairs(codes[a], codes[b], orbits, a, b);
          pairs.classify();
          // Components identify the unordered bases of the same matrix
          // space, by the basis-exchange property of its rank-one vectors.
          pairs.merge();
          total += multiplicity * pairs.mComponents.mCount;
        }
      }
    }
    return total;
  }

  /**
   * Count orbits of n-dimensional rank-one generated binary matrix spaces.
   * @param n dimension of the ambient coordinate space and the matrix space
   * @return number of orbits
   */
  public static Z count(final int n) {
    if (n > 8) {
      throw new UnsupportedOperationException("Matrices do not fit in a machine word");
    }
    return Z.valueOf(new RankOneMatrixSubspaces(n).count());
  }
}
